-- 013: new SEO titles (meta_title) and H1s (title) for blog posts, 6 Oct 2026.
-- Source: "RTI Priority A - New Titles & H1s" (Google Sheet; tabs Priority A, B, C),
-- rows whose new title / H1 is not "Keep". Pages built from code (services,
-- locations, home ...) are changed in src/data and data/url-map.csv instead.
--
-- Run once on dev and once on live:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f db/013_post_titles_h1s_oct_2026.sql
-- Safe to run twice: the second run changes the same rows to the same values.
-- og_title / twitter_title follow the new title only where they still equal
-- the old one (a hand-set social title is left alone).
-- The last query lists any slug from the sheet that is not in this database.

BEGIN;

CREATE TEMP TABLE new_titles (slug text PRIMARY KEY, meta_title text NOT NULL, h1 text NOT NULL) ON COMMIT DROP;

UPDATE posts p SET
  og_title      = CASE WHEN p.og_title = p.meta_title THEN n.meta_title ELSE p.og_title END,
  twitter_title = CASE WHEN p.twitter_title = p.meta_title THEN n.meta_title ELSE p.twitter_title END,
  meta_title    = n.meta_title,
  title         = n.h1,
  updated_at    = now()
FROM new_titles n
WHERE p.slug = n.slug
  AND (p.meta_title IS DISTINCT FROM n.meta_title OR p.title IS DISTINCT FROM n.h1);

SELECT count(*) AS posts_now_matching_sheet
  FROM posts p JOIN new_titles n ON n.slug = p.slug
 WHERE p.meta_title = n.meta_title AND p.title = n.h1;

SELECT n.slug AS not_in_this_database
  FROM new_titles n LEFT JOIN posts p ON p.slug = n.slug
 WHERE p.id IS NULL;

COMMIT;
